import { getMessaging, getToken } from "firebase/messaging";
import { initFirebaseApp } from '@imagina/qnotification/_plugins/initializeFirebaseApp.js'

import storeFirebase from '@imagina/qnotification/_store/firebase/index.ts'
import baseService from '@imagina/qcrud/_services/baseService'


export async function getTokenFirebase(userId, update) {
  if(storeFirebase.token.length > 0) return;

   const { app, firebaseWebPushCertificateKeyPair } = await initFirebaseApp();
   if(!firebaseWebPushCertificateKeyPair) return;
   notificationToken(app, firebaseWebPushCertificateKeyPair, userId, update);
}


function notificationToken(app, firebaseWebPushCertificateKeyPair, userId, update) {
  
  //Notification.requestPermission().then((permission) => {
    //if (permission === "granted") {
      console.log("Notification permission granted.");
      const messaging = getMessaging(app);
      getToken(messaging, {
        vapidKey: firebaseWebPushCertificateKeyPair,
      }).then((currentToken) => {
        console.log("Firebase token:", currentToken);
        if (currentToken) {
          if (currentToken &&  storeFirebase.token !== currentToken) {
            console.trace()
            storeFirebase.userId = userId;
            storeFirebase.token = currentToken;
            console.log('call send device ')
            storeFirebase.sendDevice();
            storeFirebase.getMessaging();
          }
        } else {
          console.log("Can not get token");
        }
      });
    //} else {
      //console.log("Do not have permission!");
    //}
  //});
}
